out=['#pragma once','#include <cstddef>','// Embedded original pt-PT "Ai!" voice and invented wobble, Ogg Opus mono 16 kHz.','namespace LumiFx {']
for name,(encoded,digest) in CLIPS.items():
    blob=zlib.decompress(base64.b85decode(encoded))
    assert hashlib.sha256(blob).hexdigest()==digest, name
    assert blob[:4]==b'OggS'
    print(name,len(blob),digest)
    out.append('static const unsigned char k'+name.capitalize()+'Ogg[] = {')
    for i in range(0,len(blob),16):
        out.append(' '+', '.join('0x%02x'%b for b in blob[i:i+16])+',')
    out.append('};')
    out.append('static constexpr size_t k'+name.capitalize()+'OggLen = sizeof(k'+name.capitalize()+'Ogg);')
out.append('}')
Path(sys.argv[1]).write_text('\n'.join(out)+'\n',encoding='utf-8')
